function locationString(loc) {
  if (!loc) return '';
  return [loc.city, loc.region, loc.countryCode].filter(Boolean).join(', ');
}

function Highlights({ items }) {
  if (!items || items.length === 0) return null;
  return (
    <Bullets>
      {items.map((h, i) => (
        <li key={i}>{h}</li>
      ))}
    </Bullets>
  );
}

