function SectionBlock({ index, title, children }) {
  return (
    <Block>
      <BlockHead>
        <Index>{`(${pad(index)})`}</Index>
        <BlockTitle>{title}</BlockTitle>
      </BlockHead>
      <BlockBody>{children}</BlockBody>
    </Block>
  );
}
